# New transform function
def find_5s_rect(grid):
    top, bottom, left, right = 999, -1, 999, -1
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == 5:
                top = min(top, i)
                bottom = max(bottom, i)
                left = min(left, j)
                right = max(right, j)
    if bottom < 0:
        return None
    return top, bottom, left, right

def transform(grid):
    rect = find_5s_rect(grid)
    if rect is None:
        return [row[:] for row in grid]
    top, bottom, left, right = rect
    # Preservation guarantees that all border cells are filled with 5s and interior cells get their appropriate values
    output = [row[:] for row in grid]

    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == 5:
                output[i][j] = 5
            else:
                d = min(i - top, bottom - i, j - left, right - j)
                if d < 3:
                    output[i][j] = 2
                elif d < 4:
                    output[i][j] = 5

    return output

